html:
{%- set ev = get_economic_evaluation(doc.name) -%}
{%- set cur = ev.currency -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=cur) }}{%- endmacro -%}
{%- set ns = namespace(cmax=1) -%}
{%- for p in ev.periods -%}
  {%- if p.revenue > ns.cmax %}{% set ns.cmax = p.revenue %}{% endif -%}
  {%- if p.total_cost > ns.cmax %}{% set ns.cmax = p.total_cost %}{% endif -%}
{%- endfor -%}
<style>
  .ee { color:#1f2933;
        font-family:-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; color:#1f2933; font-size:11px; line-height:1.4; }
  .ee *, .ee *::before, .ee *::after { box-sizing:border-box; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .ee .cover { background-color:#14532d; color:#fff; border-radius:10px; padding:20px 22px; margin-bottom:16px; border-left:6px solid #1f7a4d; }
  .ee .cover h1 { margin:0; font-size:26px; letter-spacing:.3px; }
  .ee .cover .sub { opacity:.9; font-size:12px; margin-top:2px; }
  .ee .cover .meta { width:100%; margin-top:14px; border-collapse:collapse; }
  .ee .cover .meta td { color:#eafaf1; padding:2px 10px 2px 0; font-size:11px; vertical-align:top; }
  .ee .cover .meta .k { opacity:.75; width:1%; white-space:nowrap; }
  .ee .cover .meta .v { font-weight:600; white-space:nowrap; }
  .ee h2 { font-size:14px; margin:18px 0 8px; color:#14532d; border-bottom:2px solid #1f7a4d; padding-bottom:3px; }
  .ee h2 .n { display:inline-block; background:#1f7a4d; color:#fff; border-radius:50%; width:18px; height:18px; text-align:center; line-height:18px; font-size:11px; margin-right:6px; }
  .ee .note { color:#6b7280; font-size:10px; margin:-4px 0 8px; }
  .ee .cards { width:100%; border-collapse:separate; border-spacing:8px; table-layout:fixed; }
  .ee .cards td { border:1px solid #e2e8f0; border-radius:8px; padding:8px 10px; background:#fff; vertical-align:top; }
  .ee .cards .lbl { color:#6b7280; font-size:10px; text-transform:uppercase; letter-spacing:.4px; }
  .ee .cards .val { font-size:16px; font-weight:700; margin-top:2px; }
  .ee .cards .val.pos { color:#1f7a4d; } .ee .cards .val.neg { color:#c0392b; }
  .ee .grp td { border-top:4px solid #1f7a4d; }
  .ee .grp .tag { display:inline-block; font-weight:800; color:#14532d; font-size:13px; }
  .ee .grp .desc { color:#6b7280; font-size:10px; margin-top:3px; }
  table.tb { width:100%; border-collapse:collapse; margin-bottom:6px; }
  table.tb th, table.tb td { border:1px solid #e2e8f0; padding:4px 7px; }
  table.tb th { background:#f7faf8; text-align:left; font-size:10px; text-transform:uppercase; letter-spacing:.3px; color:#334155; }
  table.tb td.n, table.tb th.n { text-align:right; white-space:nowrap; }
  table.tb tr.sub td { font-weight:700; background:#f7faf8; }
  .ee .chart { margin:8px 0 4px; white-space:nowrap; }
  .ee .col { display:inline-block; text-align:center; vertical-align:bottom; }
  .ee .bars { height:92px; }
  .ee .bars::before { content:""; display:inline-block; height:92px; width:0; vertical-align:bottom; }
  .ee .b { display:inline-block; width:38%; vertical-align:bottom; min-height:1px; }
  .ee .b.rev { background:#1f7a4d; } .ee .b.cost { background:#cbd5e1; }
  .ee .xl { font-size:8px; color:#6b7280; padding-top:2px; }
  .ee .legend { font-size:10px; color:#6b7280; margin:2px 0 10px; }
  .ee .legend .sw { display:inline-block; width:10px; height:10px; border-radius:2px; vertical-align:middle; margin:0 3px 0 10px; }
  .ee .seg { border:1px solid #e2e8f0; border-radius:8px; padding:8px 10px; margin-bottom:8px; page-break-inside:avoid; }
  .ee .seg .st { font-weight:700; color:#14532d; margin-bottom:3px; }
  .ee .seg .row { font-size:10px; margin:1px 0; }
  .ee .seg .row b { color:#334155; }
  .ee .money-pos { color:#1f7a4d; } .ee .money-neg { color:#c0392b; }
  .ee .avoid { page-break-inside:avoid; }
</style>
<div class="ee">

  <!-- 1. Identificación -->
  <div class="cover avoid">
    <h1>Evaluación Económica</h1>
    <div class="sub">Análisis financiero de la propuesta{% if ev.is_frozen %} · versión histórica (congelada){% else %} · proyección (Borrador){% endif %}</div>
    <table class="meta">
      <tr>
        <td class="k">Propuesta</td><td class="v">{{ ev.proposal_title or ev.quotation }}</td>
        <td class="k">Cotización</td><td class="v">{{ ev.quotation }}</td>
        <td class="k">Plazo contractual</td><td class="v">{{ ev.term_months }} meses</td>
      </tr>
      <tr>
        <td class="k">Cliente</td><td class="v">{{ ev.customer or "—" }}</td>
        <td class="k">Company</td><td class="v">{{ ev.company or "—" }}</td>
        <td class="k">Moneda</td><td class="v">{{ cur }}</td>
      </tr>
    </table>
  </div>

  <!-- 2. Resumen ejecutivo -->
  <h2 class="avoid"><span class="n">1</span>Resumen ejecutivo</h2>
  <table class="cards avoid">
    <tr>
      <td><div class="lbl">Ingreso contractual</div><div class="val">{{ money(ev.totals.revenue) }}</div></td>
      <td><div class="lbl">Costo externo</div><div class="val">{{ money(ev.totals.external) }}</div></td>
      <td><div class="lbl">Costo de esfuerzo</div><div class="val">{{ money(ev.totals.labor) }}</div></td>
      <td><div class="lbl">Costo total</div><div class="val">{{ money(ev.totals.total_cost) }}</div></td>
      <td><div class="lbl">Margen</div><div class="val {{ 'pos' if ev.totals.margin >= 0 else 'neg' }}">{{ money(ev.totals.margin) }}</div></td>
      <td><div class="lbl">Margen %</div><div class="val {{ 'pos' if ev.totals.margin >= 0 else 'neg' }}">{{ "%.2f"|format(ev.totals.margin_pct) }} %</div></td>
    </tr>
  </table>

  <div class="note">Distribución por agrupación (ingreso contractual)</div>
  <table class="cards grp avoid">
    <tr>
      {%- for gk, gdesc in [("NRC","Cargos no recurrentes (pago único)"),("MRC","Cargos recurrentes mensuales"),("CAPEX","Infraestructura / inversión")] %}
      {%- set g = ev.groups[gk] %}
      <td>
        <span class="tag">{{ gk }}</span>
        <div class="val">{{ money(g.revenue) }}</div>
        <div class="desc">{{ g.count }} componente(s) · {{ gdesc }}</div>
      </td>
      {%- endfor %}
    </tr>
  </table>

  <!-- 3. Fuentes de ingreso -->
  <h2><span class="n">2</span>Fuentes de ingreso</h2>
  {%- for gk in ["NRC","CAPEX"] %}{%- set g = ev.groups[gk] %}{%- if g.lines %}
  <div class="avoid">
  <div class="note"><b>{{ gk }}</b>{% if gk=="CAPEX" %} — el tratamiento financiero (inversión, plazo, tasa, mensualidad) se incorpora en Fase 2B{% endif %}</div>
  <table class="tb">
    <tr><th>Componente</th><th class="n">Cant</th><th class="n">Ingreso</th><th class="n">Costo externo</th><th class="n">Costo esfuerzo</th><th class="n">Margen</th></tr>
    {%- for l in g.lines %}
    <tr><td>{{ l.label }}</td><td class="n">{{ l.qty }}</td><td class="n">{{ money(l.revenue) }}</td><td class="n">{{ money(l.external) }}</td><td class="n">{{ money(l.labor) }}</td><td class="n">{{ money(l.margin) }}</td></tr>
    {%- endfor %}
    <tr class="sub"><td>Subtotal {{ gk }}</td><td></td><td class="n">{{ money(g.revenue) }}</td><td class="n">{{ money(g.external) }}</td><td class="n">{{ money(g.labor) }}</td><td class="n">{{ money(g.margin) }}</td></tr>
  </table>
  </div>
  {%- endif %}{%- endfor %}

  {%- set mrc = ev.groups.MRC %}{%- if mrc.lines %}
  <div class="avoid">
  <div class="note"><b>MRC</b> — recurrente durante el plazo contractual</div>
  <table class="tb">
    <tr><th>Componente</th><th class="n">Cant</th><th>Cadencia</th><th class="n">Ingreso/periodo</th><th class="n">Costo ext/periodo</th><th class="n">Periodos</th><th class="n">Ingreso contractual</th><th class="n">Costo contractual</th><th class="n">Margen</th></tr>
    {%- for l in mrc.lines %}
    <tr><td>{{ l.label }}</td><td class="n">{{ l.qty }}</td><td>{{ l.cadence }}</td><td class="n">{{ money(l.revenue_per_period) }}</td><td class="n">{{ money(l.external_per_period) }}</td><td class="n">{{ l.occurrences }}</td><td class="n">{{ money(l.revenue) }}</td><td class="n">{{ money(l.external) }}</td><td class="n">{{ money(l.margin) }}</td></tr>
    {%- endfor %}
    <tr class="sub"><td>Subtotal MRC</td><td></td><td></td><td></td><td></td><td></td><td class="n">{{ money(mrc.revenue) }}</td><td class="n">{{ money(mrc.external) }}</td><td class="n">{{ money(mrc.margin) }}</td></tr>
  </table>
  </div>
  {%- endif %}

  <!-- 4. Fuentes de costo -->
  <h2><span class="n">3</span>Fuentes de costo</h2>
  <table class="cards avoid">
    <tr>
      <td><div class="lbl">Costo externo (compras / terceros)</div><div class="val">{{ money(ev.totals.external) }}</div></td>
      <td><div class="lbl">Costo de esfuerzo (interno)</div><div class="val">{{ money(ev.totals.labor) }}</div></td>
    </tr>
  </table>
  {%- if ev.effort %}
  <div class="note">Costo de esfuerzo — Scope Items</div>
  <table class="tb">
    <tr><th>Actividad</th><th>Perfil</th><th class="n">Horas</th><th class="n">Tarifa</th><th class="n">Costo</th><th class="n">Inicio (día)</th><th class="n">Duración (día)</th><th>Periodos</th><th>Item origen</th></tr>
    {%- for e in ev.effort %}
    <tr><td>{{ e.activity }}</td><td>{{ e.designation or "" }}</td><td class="n">{{ e.hours }}</td><td class="n">{{ money(e.rate) }}</td><td class="n">{{ money(e.cost) }}</td><td class="n">{{ e.offset_days }}</td><td class="n">{{ e.duration_days }}</td><td>{% for m in e.periods %}Mes {{ m }}{% if not loop.last %}, {% endif %}{% endfor %}</td><td>{{ e.item_code }}</td></tr>
    {%- endfor %}
  </table>
  {%- endif %}

  <!-- 5. Calendario económico -->
  <h2><span class="n">4</span>Calendario económico</h2>
  <div class="chart avoid">
    {%- for p in ev.periods %}
    <div class="col" style="width:{{ (96.0 / ev.horizon)|round(2) }}%">
      <div class="bars"><span class="b rev" style="height:{{ (90.0 * p.revenue / ns.cmax)|round }}px"></span><span class="b cost" style="height:{{ (90.0 * p.total_cost / ns.cmax)|round }}px"></span></div>
      <div class="xl">{{ p.period }}</div>
    </div>
    {%- endfor %}
  </div>
  <div class="legend"><span class="sw" style="background:#1f7a4d"></span>Ingreso <span class="sw" style="background:#cbd5e1"></span>Costo total &nbsp;·&nbsp; eje X = Mes relativo</div>
  <table class="tb">
    <tr><th>Periodo</th><th class="n">Ingreso</th><th class="n">Costo externo</th><th class="n">Costo esfuerzo</th><th class="n">Costo total</th><th class="n">Margen</th><th class="n">Margen %</th></tr>
    {%- for p in ev.periods %}
    <tr><td>Mes {{ p.period }}</td><td class="n">{{ money(p.revenue) }}</td><td class="n">{{ money(p.external) }}</td><td class="n">{{ money(p.labor) }}</td><td class="n">{{ money(p.total_cost) }}</td><td class="n">{{ money(p.margin) }}</td><td class="n">{{ "%.1f"|format(100.0 * p.margin / p.revenue if p.revenue else 0) }} %</td></tr>
    {%- endfor %}
    <tr class="sub"><td>Total contractual</td><td class="n">{{ money(ev.totals.revenue) }}</td><td class="n">{{ money(ev.totals.external) }}</td><td class="n">{{ money(ev.totals.labor) }}</td><td class="n">{{ money(ev.totals.total_cost) }}</td><td class="n">{{ money(ev.totals.margin) }}</td><td class="n">{{ "%.2f"|format(ev.totals.margin_pct) }} %</td></tr>
  </table>

  <!-- 6. Trazabilidad -->
  <h2><span class="n">5</span>Trazabilidad de flujos</h2>
  <div class="note">Cada cifra se explica por sus componentes. Los meses idénticos se agrupan.</div>
  {%- for s in ev.calendar_segments %}
  <div class="seg">
    <div class="st">{{ s.label }}{% if s.months > 1 %} · {{ s.months }} meses iguales{% endif %}
      &nbsp;—&nbsp; Ingreso {{ money(s.revenue) }} · Costo {{ money(s.total_cost) }} · Margen <span class="{{ 'money-pos' if s.margin>=0 else 'money-neg' }}">{{ money(s.margin) }}</span></div>
    {%- if s.revenue_components %}<div class="row"><b>Ingreso:</b> {% for c in s.revenue_components %}+{{ money(c.amount) }} {{ c.item_code }} ({{ c.group }}){% if not loop.last %} · {% endif %}{% endfor %}</div>{% endif %}
    {%- if s.external_components %}<div class="row"><b>Costo externo:</b> {% for c in s.external_components %}−{{ money(c.amount) }} {{ c.item_code }}{% if not loop.last %} · {% endif %}{% endfor %}</div>{% endif %}
    {%- if s.labor_components %}<div class="row"><b>Costo de esfuerzo:</b> {% for c in s.labor_components %}−{{ money(c.amount) }} {{ c.activity }}{% if not loop.last %} · {% endif %}{% endfor %}</div>{% endif %}
  </div>
  {%- endfor %}

</div>
